#include "MainWindow.hpp"
#include "ui_MainWindow.h" // Generated by the MOC

#include <memory>
#include <print>
#include "AddMaterialDialog.hpp"


MainWindow::MainWindow(QWidget* parent)
: QMainWindow(parent)
, m_impl(new Ui::MainWindow)
{
  m_impl->setupUi(this);

  connect(m_impl->actionAddMaterial, &QAction::triggered, this, &MainWindow::onAddMaterial);
  connect(m_impl->actionInterfParams, &QAction::triggered, this, &MainWindow::onInterfParams);
  connect(m_impl->actionOutputParams, &QAction::triggered, this, &MainWindow::onOutputParams);
  connect(m_impl->actionViewMaterials, &QAction::triggered, this, &MainWindow::onViewMaterials);

  connect(m_impl->addLayerButton, &QPushButton::clicked, this, &MainWindow::onAddLayer);
  connect(m_impl->removeLayerButton, &QPushButton::clicked, this, &MainWindow::onRemoveLayer);
  connect(m_impl->importStackButton, &QPushButton::clicked, this, &MainWindow::onImportStack);
  connect(m_impl->exportStackButton, &QPushButton::clicked, this, &MainWindow::onExportStack);
  connect(m_impl->computeStackButton, &QPushButton::clicked, this, &MainWindow::onComputeStack);

  m_materials["bulkSilica"] = Material("bulkSilica", 1e-9, 1e-6, 1e-6, 1, 1e6, 1.45, 73.2e9, 0.17, 1e-9);

  m_interferometer.beamWidth = 0.062;
  m_interferometer.wavelength = 1064e-9;
  m_interferometer.temperature = 290.0;
}

MainWindow::~MainWindow()
{
  delete m_impl;
}

void MainWindow::onAddMaterial()
{
  // TODO: Should the dialog be made once, reset and reused?
  //   Will need a reset function
  auto addMaterialDialog = std::make_shared<AddMaterialDialog>();

  if (addMaterialDialog->exec())
  {
    bool result = false;
    if (addMaterialDialog)
    {
      result = true;
    }
  }
}

